__bpf_object__open(const char *path, const void *obj_buf, size_t obj_buf_sz,
                   const struct bpf_object_open_opts *opts)
{
        const char *obj_name, *kconfig, *btf_tmp_path;
        struct bpf_object *obj;
        char tmp_name[64];
        int err;

        if (elf_version(EV_CURRENT) == EV_NONE) {
                pr_warn("failed to init libelf for %s\n",
                        path ? : "(mem buf)");
                return ERR_PTR(-LIBBPF_ERRNO__LIBELF);
        }

        if (!OPTS_VALID(opts, bpf_object_open_opts))
                return ERR_PTR(-EINVAL);

        obj_name = OPTS_GET(opts, object_name, NULL);
        if (obj_buf) {
                if (!obj_name) {
                        snprintf(tmp_name, sizeof(tmp_name), "%lx-%lx",
                                 (unsigned long)obj_buf,
                                 (unsigned long)obj_buf_sz);
                        obj_name = tmp_name;
                }
                path = obj_name;
                pr_debug("loading object '%s' from buffer\n", obj_name);
        }

        obj = bpf_object__new(path, obj_buf, obj_buf_sz, obj_name);
        if (IS_ERR(obj))
                return obj;

        btf_tmp_path = OPTS_GET(opts, btf_custom_path, NULL);
        if (btf_tmp_path) {
                if (strlen(btf_tmp_path) >= PATH_MAX) {
                        err = -ENAMETOOLONG;
                        goto out;
                }
                obj->btf_custom_path = strdup(btf_tmp_path);
                if (!obj->btf_custom_path) {
                        err = -ENOMEM;
                        goto out;
                }
        }

        kconfig = OPTS_GET(opts, kconfig, NULL);
        if (kconfig) {
                obj->kconfig = strdup(kconfig);
                if (!obj->kconfig) {
                        err = -ENOMEM;
                        goto out;
                }
        }

        err = bpf_object__elf_init(obj);
        err = err ? : bpf_object__check_endianness(obj);
        err = err ? : bpf_object__elf_collect(obj);
        err = err ? : bpf_object__collect_externs(obj);
        err = err ? : bpf_object__finalize_btf(obj);
        err = err ? : bpf_object__init_maps(obj, opts);
        err = err ? : bpf_object_init_progs(obj, opts);
        err = err ? : bpf_object__collect_relos(obj);
        if (err)
                goto out;

        bpf_object__elf_finish(obj);

        return obj;
out:
        bpf_object__close(obj);
        return ERR_PTR(err);
}

static struct bpf_object *
__bpf_object__open_xattr(struct bpf_object_open_attr *attr, int flags)
{
        DECLARE_LIBBPF_OPTS(bpf_object_open_opts, opts,
                .relaxed_maps = flags & MAPS_RELAX_COMPAT,
        );

        /* param validation */
        if (!attr->file)
                return NULL;

        pr_debug("loading %s\n", attr->file);
        return __bpf_object__open(attr->file, NULL, 0, &opts);
}

struct bpf_object *bpf_object__open_xattr(struct bpf_object_open_attr *attr)
{
        return libbpf_ptr(__bpf_object__open_xattr(attr, 0));
}

struct bpf_object *bpf_object__open(const char *path)
{
        struct bpf_object_open_attr attr = {
                .file           = path,
                .prog_type      = BPF_PROG_TYPE_UNSPEC,
        };

        return libbpf_ptr(__bpf_object__open_xattr(&attr, 0));
}

struct bpf_object *
bpf_object__open_file(const char *path, const struct bpf_object_open_opts *opts)
{
        if (!path)
                return libbpf_err_ptr(-EINVAL);

        pr_debug("loading %s\n", path);

        return libbpf_ptr(__bpf_object__open(path, NULL, 0, opts));
}

struct bpf_object *
bpf_object__open_mem(const void *obj_buf, size_t obj_buf_sz,
                     const struct bpf_object_open_opts *opts)
{
        if (!obj_buf || obj_buf_sz == 0)
                return libbpf_err_ptr(-EINVAL);

        return libbpf_ptr(__bpf_object__open(NULL, obj_buf, obj_buf_sz, opts));
}

struct bpf_object *
bpf_object__open_buffer(const void *obj_buf, size_t obj_buf_sz,
                        const char *name)
{
        DECLARE_LIBBPF_OPTS(bpf_object_open_opts, opts,
                .object_name = name,
                /* wrong default, but backwards-compatible */
                .relaxed_maps = true,
        );

        /* returning NULL is wrong, but backwards-compatible */
        if (!obj_buf || obj_buf_sz == 0)
                return errno = EINVAL, NULL;

        return libbpf_ptr(__bpf_object__open(NULL, obj_buf, obj_buf_sz, &opts));
}

static int bpf_object_unload(struct bpf_object *obj)
{
        size_t i;

        if (!obj)
                return libbpf_err(-EINVAL);

        for (i = 0; i < obj->nr_maps; i++) {
                zclose(obj->maps[i].fd);
                if (obj->maps[i].st_ops)
                        zfree(&obj->maps[i].st_ops->kern_vdata);
        }

        for (i = 0; i < obj->nr_programs; i++)
                bpf_program__unload(&obj->programs[i]);

        return 0;
}

int bpf_object__unload(struct bpf_object *obj) __attribute__((alias("bpf_object_unload")));

static int bpf_object__sanitize_maps(struct bpf_object *obj)
{
        struct bpf_map *m;

        bpf_object__for_each_map(m, obj) {
                if (!bpf_map__is_internal(m))
                        continue;
                if (!kernel_supports(obj, FEAT_GLOBAL_DATA)) {
                        pr_warn("kernel doesn't support global data\n");
                        return -ENOTSUP;
                }
                if (!kernel_supports(obj, FEAT_ARRAY_MMAP))
                        m->def.map_flags ^= BPF_F_MMAPABLE;
        }

        return 0;
}

